import seaborn as sns
import pandas as pd
def task_func(json_data: str, key_path: list):
    data = json.loads(json_data)
    current = data
    for key in key_path:
        if key not in current:
            raise KeyError(f"Key '{key}' not found in path.")
        current = current[key]

    if not isinstance(current, list) or len(current) == 0:
        raise ValueError("Data is empty or not in a valid list format.")

    numeric_data = []
    for item in current:
        try:
            numeric_data.append(float(item))
        except (ValueError, TypeError):
            continue

    if not numeric_data:
        raise ValueError("No valid numeric data found.")

    fig, ax = plt.subplots()
    sns.boxplot(data=numeric_data, ax=ax)
    return fig

